#!/usr/bin/env python3
"""
Rebuilds the four Treatments pages in Hertility's structure, in FertiTerra branding.

Hertility's Treatments menu has four destinations, and each page has its own
shape rather than one shared template. This builds a small section renderer
(prose, numbered steps, cards, side-by-side comparison, price table, CTA band,
FAQ, link cards) and composes the four pages from it.

Routes created:
  /treatments/ivf-support
  /treatments/egg-freezing
  /treatments/lgbtqia-family
  /treatments/trusted-clinics

The four Treatments menu links are repointed to them. Your existing pages
(/treatments, /appointments/egg-freezing, /learn/lgbtqia-family,
/trusted-clinics) are left exactly as they are.
"""
import base64
import json
from pathlib import Path

FILES = json.loads(base64.b64decode("").decode())
PAGES = json.loads(base64.b64decode("").decode())

MENU = [
    ('{ label: "IVF support", href: "/treatments" }',
     '{ label: "IVF support", href: "/treatments/ivf-support" }'),
    ('{ label: "Egg freezing", href: "/appointments/egg-freezing" }',
     '{ label: "Egg freezing", href: "/treatments/egg-freezing" }'),
    ('{ label: "Starting an LGBTQIA+ family", href: "/learn/lgbtqia-family" }',
     '{ label: "Starting an LGBTQIA+ family", href: "/treatments/lgbtqia-family" }'),
    ('{ label: "Trusted clinics", href: "/trusted-clinics" }',
     '{ label: "Trusted clinics", href: "/treatments/trusted-clinics" }'),
]

TEMPLATE = '''import type { Metadata } from "next"
import { TreatmentPage } from "@/components/ft/treatment-page"

export const metadata: Metadata = {
  title: "%s | FertiTerra",
}

export default function Page() {
  return <TreatmentPage slug="%s" />
}
'''


def main():
    if not Path("package.json").is_file() or not Path("app").is_dir():
        print("Run this from the Fertiterra folder.")
        return

    print("1. Section renderer and page content")
    for rel, content in FILES.items():
        p = Path(rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.is_file() and p.read_text(encoding="utf-8") == content:
            print("   already current: " + rel)
            continue
        p.write_text(content, encoding="utf-8")
        print("   wrote " + rel)

    print("")
    print("2. The four Treatments pages")
    for d, meta in PAGES.items():
        slug, title = meta
        p = Path(d)
        p.mkdir(parents=True, exist_ok=True)
        f = p / "page.tsx"
        body = TEMPLATE % (title, slug)
        if f.is_file():
            existing = f.read_text(encoding="utf-8")
            if existing == body:
                print("   already current: " + d)
                continue
            (p / "page.tsx.bak-before-treatment-rebuild").write_text(existing, encoding="utf-8")
        f.write_text(body, encoding="utf-8")
        print("   created " + d)

    print("")
    print("3. Treatments menu links")
    header = Path("components/header.tsx")
    if not header.is_file():
        print("   components/header.tsx not found, menu left alone")
    else:
        src = header.read_text(encoding="utf-8")
        changed = 0
        for old, new in MENU:
            if new in src:
                print("   already points at " + new.split('href: "')[1].split('"')[0])
            elif old in src:
                src = src.replace(old, new)
                changed += 1
                print("   repointed " + new.split('label: "')[1].split('"')[0])
            else:
                print("   not found, left alone: " + old.split('label: "')[1].split('"')[0])
        if changed:
            header.with_suffix(".tsx.bak-before-treatment-menu").write_text(
                header.read_text(encoding="utf-8"), encoding="utf-8"
            )
            header.write_text(src, encoding="utf-8")

    print("")
    print("Check it compiles:")
    print("   npx tsc --noEmit 2>&1 | grep treatments")
    print("")
    print("If any page 404s, restart the dev server: Ctrl+C, then rm -rf .next && pnpm dev")
    print("")
    print("Then open:")
    for d in PAGES:
        print("   http://localhost:3000/" + d.replace("app/", ""))


if __name__ == "__main__":
    main()
